def build(wave_name, items, wave_id, milestone):
    seen = set()
    out = []
    for i in items:
        assert i["name"] not in seen, i["name"]
        seen.add(i["name"])
        out.append({**i, "prompt": sub(i["prompt"], wave_name)})
    spec = {"wave": wave_id, "reportDir": ".ufo/waves/round-31/" + wave_name, "maxLanes": 128,
            "axes": ["depth:verifiability", "coverage"], "milestone": milestone,
            "context": sub(CONTEXT, wave_name), "items": out}
    path = os.path.join(RD, wave_name + "-spec.json")
    json.dump(spec, open(path, "w"), indent=1, ensure_ascii=False)
    from collections import Counter
    print(path, len(out), dict(Counter(i["role"] for i in out)))


